    "Graph.c": "// Implementation of the undirected graph ADT using an adjacency matrix\n\n// !!! DO NOT MODIFY THIS FILE !!!\n\n#include <assert.h>\n#include <stdbool.h>\n#include <stdio.h>\n#include <stdlib.h>\n\n#include \"Graph.h\"\n\nstatic bool validVertex(Graph g, Vertex v);\n\n////////////////////////////////////////////////////////////////////////\n\nGraph GraphNew(int nV) {\n    assert(nV > 0);\n\n    Graph g = malloc(sizeof(*g));\n    if (g == NULL) {\n        fprintf(stderr, \"error: out of memory\\n\");\n        exit(EXIT_FAILURE);\n    }\n\n    g->nV = nV;\n    g->nE = 0;\n\n    g->edges = malloc(nV * sizeof(bool *));\n    if (g->edges == NULL) {\n        fprintf(stderr, \"error: out of memory\\n\");\n        exit(EXIT_FAILURE);\n    }\n    for (int i = 0; i < nV; i++) {\n        g->edges[i] = calloc(nV, sizeof(bool));\n        if (g->edges[i] == NULL) {\n            fprintf(stderr, \"error: out of memory\\n\");\n            exit(EXIT_FAILURE);\n        }\n    }\n\n    return g;\n}\n\nvoid GraphFree(Graph g) {\n    for (int i = 0; i < g->nV; i++) {\n        free(g->edges[i]);\n    }\n    free(g->edges);\n    free(g);\n}\n\n////////////////////////////////////////////////////////////////////////\n\nint GraphNumVertices(Graph g) {\n    return g->nV;\n}\n\nvoid GraphInsertEdge(Graph g, Vertex v, Vertex w) {\n    assert(validVertex(g, v));\n    assert(validVertex(g, w));\n    assert(v != w);\n\n    if (!g->edges[v][w]) {\n        g->edges[v][w] = true;\n        g->edges[w][v] = true;\n        g->nE++;\n    }\n}\n\nbool GraphIsAdjacent(Graph g, Vertex u, Vertex v) {\n    assert(validVertex(g, u));\n    assert(validVertex(g, v));\n\n    return g->edges[u][v];\n}\n\nvoid GraphShow(Graph g) {\n    printf(\"Number of vertices: %d\\n\", g->nV);\n    printf(\"Number of edges: %d\\n\", g->nE);\n    printf(\"Edges:\\n\");\n    for (int v = 0; v < g->nV; v++) {\n        printf(\"%2d:\", v);\n        for (int w = 0; w < g->nV; w++) {\n            if (g->edges[v][w]) {\n                printf(\" %d\", w);\n            }\n        }\n        printf(\"\\n\");\n    }\n}\n\n////////////////////////////////////////////////////////////////////////\n\nstatic bool validVertex(Graph g, Vertex v) {\n    return v >= 0 && v < g->nV;\n}\n",
    "Queue.c": "// Implementation of the queue ADT\n\n// !!! DO NOT MODIFY THIS FILE !!!\n\n#include <assert.h>\n#include <stdbool.h>\n#include <stdio.h>\n#include <stdlib.h>\n\n#include \"Queue.h\"\n\nstruct queue {\n    struct node *head;\n    struct node *tail;\n    int size;\n};\n\nstruct node {\n    Item item;\n    struct node *next;\n};\n\nstatic struct node *newNode(Item it);\n\nQueue QueueNew(void) {\n    Queue q = malloc(sizeof(struct queue));\n    if (q == NULL) {\n        fprintf(stderr, \"error: out of memory\\n\");\n        exit(EXIT_FAILURE);\n    }\n\n    q->head = NULL;\n    q->tail = NULL;\n    q->size = 0;\n    return q;\n}\n\nvoid QueueFree(Queue q) {\n    struct node *curr = q->head;\n    while (curr != NULL) {\n        struct node *temp = curr;\n        curr = curr->next;\n        free(temp);\n    }\n    free(q);\n}\n\nvoid QueueEnqueue(Queue q, Item it) {\n    struct node *n = newNode(it);\n    if (q->size == 0) {\n        q->head = n;\n    } else {\n        q->tail->next = n;\n    }\n    q->tail = n;\n    q->size++;\n}\n\nstatic struct node *newNode(Item it) {\n    struct node *n = malloc(sizeof(*n));\n    if (n == NULL) {\n        fprintf(stderr, \"error: out of memory\\n\");\n        exit(EXIT_FAILURE);\n    }\n\n    n->item = it;\n    n->next = NULL;\n    return n;\n}\n\nItem QueueDequeue(Queue q) {\n    if (q->size == 0) {\n        fprintf(stderr, \"error: queue is empty!\\n\");\n        return 0;\n    }\n\n    struct node *newHead = q->head->next;\n    Item it = q->head->item;\n\n    free(q->head);\n    q->head = newHead;\n    if (newHead == NULL) {\n        q->tail = NULL;\n    }\n    q->size--;\n\n    return it;\n}\n\nint QueueSize(Queue q) {\n    return q->size;\n}\n\nbool QueueIsEmpty(Queue q) {\n    return q->size == 0;\n}\n\nItem QueuePeek(Queue q) {\n    if (q->size == 0) {\n        fprintf(stderr, \"error: queue is empty!\\n\");\n        return 0;\n    }\n\n    return q->head->item;\n}\n"
