  "listDeleteDuplicates": {
    "list.h": "// A singly linked list of integers\n\n#ifndef LIST_H\n#define LIST_H\n\n#include <stdbool.h>\n\n#define MAX_LINE_LEN 1024\n\nstruct node {\n    int value;\n    struct node *next;\n};\n\nstruct list {\n    struct node *head;\n};\n\n/**\n * Creates a new empty list\n */\nstruct list *listNew(void);\n\n////////////////////////////////////////////////////////////////////////\n// You should not use the functions below\n\n/**\n * Frees all memory associated with the given list\n */\nvoid listFree(struct list *l);\n\n/**\n * Prints a list in the standard format. For example,\n * [1] -> [2] -> [3] -> X\n */\nvoid listPrint(struct list *l);\n\n/**\n * Prints a list in a set format. For example, the list 1 -> 2 -> 3 -> X\n * is printed as {1, 2, 3}.\n */\nvoid listPrintAsSet(struct list *l);\n\n/**\n * Reads  in  a line of integers from stdin and converts it into a list.\n * Assumes  that the line consists entirely of space-separated integers,\n * and that the line is no longer than 1024 characters.\n */\nstruct list *listRead(void);\n\n/**\n * Returns a sorted copy of the given list.\n */\nstruct list *listSortedCopy(struct list *l);\n\n#endif\n",
    "listDeleteDuplicates.c": "#include <stdbool.h>\n#include <stdio.h>\n#include <stdlib.h>\n\n#include \"list.h\"\n\nvoid listDeleteDuplicates(struct list *l) {\n    // TODO\n    \n}\n",
    "list.c": "// A singly linked list of integers\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\n#include \"list.h\"\n\nstatic struct list *strToList(char *s);\nstatic char *strDup(char *s);\nstatic struct node *newNode(int value);\nstatic struct node *sortedInsert(struct node *head, int val);\n\nstruct list *listNew(void) {\n    struct list *l = malloc(sizeof(*l));\n    if (l == NULL) {\n        fprintf(stderr, \"error: out of memory\\n\");\n        exit(EXIT_FAILURE);\n    }\n    l->head = NULL;\n    return l;\n}\n\nvoid listFree(struct list *l) {\n    struct node *curr = l->head;\n    while (curr != NULL) {\n        struct node *temp = curr;\n        curr = curr->next;\n        free(temp);\n    }\n    free(l);\n}\n\nvoid listPrint(struct list *l) {\n    struct node *curr = l->head;\n    while (curr != NULL) {\n        printf(\"[%d] -> \", curr->value);\n        curr = curr->next;\n    }\n    printf(\"X\\n\");\n}\n\nvoid listPrintAsSet(struct list *l) {\n    printf(\"{\");\n    for (struct node *curr = l->head; curr != NULL; curr = curr->next) {\n        printf(\"%d\", curr->value);\n        if (curr->next != NULL) {\n            printf(\", \");\n        }\n    }\n    printf(\"}\\n\");\n}\n\nstruct list *listRead(void) {\n    char buf[MAX_LINE_LEN + 2] = {0};\n    fgets(buf, MAX_LINE_LEN + 2, stdin);\n    return strToList(buf);\n}\n\nstatic struct list *strToList(char *s) {\n    char *copy = strDup(s);\n    struct node *head = NULL;\n    struct node *curr = NULL;\n    char *token = strtok(copy, \" \\n\\t\");\n    while (token != NULL) {\n        struct node *n = newNode(atoi(token));\n        if (head == NULL) {\n            head = n;\n        } else {\n            curr->next = n;\n        }\n        curr = n;\n        token = strtok(NULL, \" \\n\\t\");\n    }\n    free(copy);\n    struct list *l = listNew();\n    l->head = head;\n    return l;\n}\n\nstatic char *strDup(char *s) {\n    char *copy = malloc((strlen(s) + 1) * sizeof(char));\n    strcpy(copy, s);\n    return copy;\n}\n\nstatic struct node *newNode(int value) {\n    struct node *n = malloc(sizeof(*n));\n    if (n == NULL) {\n        fprintf(stderr, \"error: out of memory\\n\");\n        exit(EXIT_FAILURE);\n    }\n    n->value = value;\n    n->next = NULL;\n    return n;\n}\n\nstruct list *listSortedCopy(struct list *l) {\n    struct list *copy = listNew();\n    for (struct node *curr = l->head; curr != NULL; curr = curr->next) {\n        copy->head = sortedInsert(copy->head, curr->value);\n    }\n    return copy;\n}\n\nstatic struct node *sortedInsert(struct node *head, int val) {\n    if (head == NULL || val <= head->value) {\n        struct node *n = newNode(val);\n        n->next = head;\n        return n;\n    } else {\n        head->next = sortedInsert(head->next, val);\n        return head;\n    }\n}\n"
  },
