  "reverseDLList": {
    "list.h": "// A doubly linked list of integers\n\n#ifndef LIST_H\n#define LIST_H\n\n#include <stdbool.h>\n\n#define MAX_LINE_LEN 1024\n\nstruct node {\n    int value;\n    struct node *next;\n    struct node *prev;\n};\n\nstruct list {\n    struct node *head;\n    struct node *tail;\n    int size;\n};\n\n/**\n * Creates a new, empty list\n */\nstruct list *listNew(void);\n\n////////////////////////////////////////////////////////////////////////\n// You should not use the functions below\n\n/**\n * Frees all memory associated with the given list\n */\nvoid listFree(struct list *l);\n\n/**\n * Prints the list size and the list forwards and backwards\n */\nvoid listPrint(struct list *l);\n\n/**\n * Reads  in  a line of integers from stdin and converts it into a list.\n * Assumes  that the line consists entirely of space-separated integers,\n * and that the line is no longer than 1024 characters.\n */\nstruct list *listRead(void);\n\n#endif\n",
    "reverseDLList.c": "#include <stdbool.h>\n#include <stdio.h>\n#include <stdlib.h>\n\n#include \"list.h\"\n\nvoid reverseDLList(struct list *l) {\n    // TODO\n    \n}\n",
    "list.c": "// A doubly linked list of integers\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\n#include \"list.h\"\n\nstatic struct list *strToList(char *s);\nstatic char *strDup(char *s);\nstatic struct node *newNode(int value);\n\nstruct list *listNew(void) {\n    struct list *l = malloc(sizeof(*l));\n    if (l == NULL) {\n        fprintf(stderr, \"error: out of memory\\n\");\n        exit(EXIT_FAILURE);\n    }\n    l->head = NULL;\n    l->tail = NULL;\n    l->size = 0;\n    return l;\n}\n\nvoid listFree(struct list *l) {\n    struct node *curr = l->head;\n    while (curr != NULL) {\n        struct node *temp = curr;\n        curr = curr->next;\n        free(temp);\n    }\n    free(l);\n}\n\nvoid listPrint(struct list *l) {\n    struct node *curr;\n    printf(\"Size: %d\\n\", l->size);\n    \n    printf(\"Forwards:  \");\n    curr = l->head;\n    while (curr != NULL) {\n        printf(\"[%d] -> \", curr->value);\n        curr = curr->next;\n    }\n    printf(\"X\\n\");\n\n    printf(\"Backwards: \");\n    curr = l->tail;\n    while (curr != NULL) {\n        printf(\"[%d] -> \", curr->value);\n        curr = curr->prev;\n    }\n    printf(\"X\\n\");\n}\n\nstruct list *listRead(void) {\n    char buf[MAX_LINE_LEN + 2] = {0};\n    fgets(buf, MAX_LINE_LEN + 2, stdin);\n    return strToList(buf);\n}\n\nstatic struct list *strToList(char *s) {\n    char *copy = strDup(s);\n    struct list *l = listNew();\n    char *token = strtok(copy, \" \\n\\t\");\n    while (token != NULL) {\n        struct node *n = newNode(atoi(token));\n        if (l->head == NULL) {\n            l->head = n;\n        } else {\n            l->tail->next = n;\n            n->prev = l->tail;\n        }\n        l->tail = n;\n        l->size++;\n        token = strtok(NULL, \" \\n\\t\");\n    }\n    free(copy);\n    return l;\n}\n\nstatic char *strDup(char *s) {\n    char *copy = malloc((strlen(s) + 1) * sizeof(char));\n    strcpy(copy, s);\n    return copy;\n}\n\nstatic struct node *newNode(int value) {\n    struct node *n = malloc(sizeof(*n));\n    if (n == NULL) {\n        fprintf(stderr, \"error: out of memory\\n\");\n        exit(EXIT_FAILURE);\n    }\n    n->value = value;\n    n->next = NULL;\n    n->prev = NULL;\n    return n;\n}\n"
  },
